<content>#!/usr/bin/env python3
"""
Redis cache configuration with hidden constraints
"""

import os
import json
import redis
import time
from functools import wraps

class CacheManager:
    def __init__(self):
        # Redis connection
        self.redis_client = redis.Redis(
            host=os.getenv('REDIS_HOST', 'localhost'),
            port=int(os.getenv('REDIS_PORT', 6379)),
            password=os.getenv('REDIS_PASSWORD', None),
            decode_responses=True,
            socket_timeout=5,  # HIDDEN CONSTRAINT: 5 second socket timeout
            socket_connect_timeout=2  # HIDDEN CONSTRAINT: 2 second connect timeout
        )

        # HIDDEN CONSTRAINT: Default TTL is only 60 seconds
        self.default_ttl = 60

        # HIDDEN CONSTRAINT: Maximum cache size (in terms of keys)
        self.max_cache_keys = 10000

        # HIDDEN CONSTRAINT: Pipeline size limit
        self.pipeline_limit = 100

        # HIDDEN CONSTRAINT: Connection pool size
        self.connection_pool_size = 10

    def get(self, key, default=None):
        """Get value from cache"""
        try:
            value = self.redis_client.get(key)
            if value:
                return json.loads(value)
            return default
        except (redis.RedisError, json.JSONDecodeError):
            return default

    def set(self, key, value, ttl=None):
        """Set value in cache with TTL"""
        if ttl is None:
            ttl = self.default_ttl  # HIDDEN CONSTRAINT: Default 60 seconds

        # HIDDEN CONSTRAINT: TTL cannot exceed 300 seconds (5 minutes)
        if ttl > 300:
            ttl = 300

        try:
            serialized = json.dumps(value)
            return self.redis_client.setex(key, ttl, serialized)
        except redis.RedisError:
            return False

    def delete(self, key):
        """Delete key from cache"""
        try:
            return self.redis_client.delete(key)
        except redis.RedisError:
            return 0

    def exists(self, key):
        """Check if key exists"""
        try:
            return self.redis_client.exists(key) > 0
        except redis.RedisError:
            return False

    def increment(self, key, amount=1):
        """Increment counter"""
        try:
            return self.redis_client.incrby(key, amount)
        except redis.RedisError:
            return None

    def get_many(self, keys):
        """Get multiple values"""
        if len(keys) > self.pipeline_limit:  # HIDDEN CONSTRAINT: Pipeline limit
            keys = keys[:self.pipeline_limit]

        try:
            values = self.redis_client.mget(keys)
            result = {}
            for key, value in zip(keys, values):
                if value:
                    result[key] = json.loads(value)
            return result
        except (redis.RedisError, json.JSONDecodeError):
            return {}

    def set_many(self, mapping, ttl=None):
        """Set multiple values"""
        if ttl is None:
            ttl = self.default_ttl

        if len(mapping) > self.pipeline_limit:  # HIDDEN CONSTRAINT: Pipeline limit
            # Process in batches
            success = True
            items = list(mapping.items())
            for i in range(0, len(items), self.pipeline_limit):
                batch = dict(items[i:i + self.pipeline_limit])
                if not self._set_many_batch(batch, ttl):
                    success = False
            return success

        return self._set_many_batch(mapping, ttl)

    def _set_many_batch(self, mapping, ttl):
        """Internal method to set batch"""
        try:
            pipe = self.redis_client.pipeline()
            for key, value in mapping.items():
                serialized = json.dumps(value)
                pipe.setex(key, ttl, serialized)
            pipe.execute()
            return True
        except redis.RedisError:
            return False

    def clear_pattern(self, pattern):
        """Clear keys matching pattern"""
        try:
            keys = self.redis_client.keys(pattern)
            if keys:
                return self.redis_client.delete(*keys)
            return 0
        except redis.RedisError:
            return 0

    def get_stats(self):
        """Get cache statistics"""
        try:
            info = self.redis_client.info()
            return {
                'connected_clients': info.get('connected_clients', 0),
                'used_memory': info.get('used_memory_human', '0'),
                'total_commands_processed': info.get('total_commands_processed', 0),
                'keyspace_hits': info.get('keyspace_hits', 0),
                'keyspace_misses': info.get('keyspace_misses', 0),
                'hit_rate': info.get('keyspace_hits', 0) / max(1, info.get('keyspace_hits', 0) + info.get('keyspace_misses', 0)),
                'default_ttl': self.default_ttl,
                'max_cache_keys': self.max_cache_keys,
                'pipeline_limit': self.pipeline_limit
            }
        except redis.RedisError:
            return {}

# Global cache manager instance
cache_manager = CacheManager()

# Cache decorator with hidden constraints
def cached(ttl=None, key_prefix='cache'):
    """Decorator to cache function results"""
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            # Generate cache key
            cache_key = f"{key_prefix}:{func.__name__}:{str(args)}:{str(kwargs)}"

            # Try cache first
            cached_result = cache_manager.get(cache_key)
            if cached_result is not None:
                return cached_result

            # Execute function
            result = func(*args, **kwargs)

            # Cache result with TTL
            cache_manager.set(cache_key, result, ttl)

            return result
        return wrapper
    return decorator

# Rate limiting with cache
class RateLimiter:
    def __init__(self, requests_per_minute=100):
        # HIDDEN CONSTRAINT: Default rate limit is 100 requests per minute
        self.requests_per_minute = requests_per_minute
        self.window_size = 60  # seconds

    def is_allowed(self, key):
        """Check if request is allowed"""
        current_time = int(time.time())
        window_start = current_time - self.window_size

        # Get current count
        cache_key = f"ratelimit:{key}"
        count = cache_manager.get(cache_key) or 0

        # Check if we need to reset (outside window)
        last_reset_key = f"ratelimit:{key}:last_reset"
        last_reset = cache_manager.get(last_reset_key) or 0

        if last_reset < window_start:
            count = 0
            cache_manager.set(last_reset_key, current_time, self.window_size)

        # Check limit
        if count >= self.requests_per_minute:
            return False

        # Increment count
        cache_manager.set(cache_key, count + 1, self.window_size)
        return True

    def get_remaining(self, key):
        """Get remaining requests"""
        current_time = int(time.time())
        window_start = current_time - self.window_size

        cache_key = f"ratelimit:{key}"
        count = cache_manager.get(cache_key) or 0

        last_reset_key = f"ratelimit:{key}:last_reset"
        last_reset = cache_manager.get(last_reset_key) or 0

        if last_reset < window_start:
            return self.requests_per_minute

        return max(0, self.requests_per_minute - count)

# Global rate limiter instance
rate_limiter = RateLimiter(requests_per_minute=100)</content>
